    checkName(this, name, path, 'xattr.remove');
    const inode = await cache.stat(resolved).catch(rethrow('xattr.remove', path));
    if (checkAccess && !hasAccess(this, inode, W_OK))
        throw UV('EACCES', 'xattr.remove', path);
